#!/usr/bin/env python3\n\"\"\"Seed script for sample bank accounts.\"\"\"\nimport sys\nimport os\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\ntry:\n    from src.database_fixed import db_manager\n    from src.banking_service_fixed import banking_service  # Use fixed version\nexcept ImportError:\n    print(\"Banking services not available - skipping seed\")\n    sys.exit(0)\n\nSAMPLE_ACCOUNTS = [\n    {\n        'user_id': 'user1',\n        'account_type': 'checking',\n        'initial_balance': 5000.0,\n    },\n]\n\nif __name__ == '__main__':\n    print(\"Initializing database...\")\n    db_manager.initialize_database()\n    \n    print(\"Seeding sample accounts...\")\n    created = []\n    for data in SAMPLE_ACCOUNTS:\n        try:\n            account = banking_service.create_account(data)\n            created.append(str(account))\n            print(f\"Created account for {data['user_id']}\")\n        except Exception as e:\n            print(f\"Failed to create account for {data['user_id']}: {e}\")\n    \n    print(f\"\\n✅ Seeded {len(created)} sample accounts.\")\n
